const input = $input.first()?.json ?? {};
const fail = (message) => { throw new Error(`INVALID_CONTEXT_INPUT: ${message}`); };
if (String(input.schema_version ?? '') !== '1.0') fail('schema_version must equal 1.0');
if (input.operation !== 'build_chapter_context') fail('operation must equal build_chapter_context');
const novelId = String(input.novel?.novel_id ?? '').trim();
if (!novelId) fail('novel.novel_id is required');
if (!/^NOVEL\d+$/.test(novelId)) fail('novel.novel_id must match NOVEL+digits');
const novelName = String(input.novel?.novel_name ?? '').trim();
if (!novelName) fail('novel.novel_name is required');
const chapterNo = input.chapter?.next_chapter_no;
if (!Number.isInteger(chapterNo) || chapterNo <= 0) fail('chapter.next_chapter_no must be a positive integer');
const chapterId = String(input.chapter?.next_chapter_id ?? '').trim();
if (!chapterId) fail('chapter.next_chapter_id is required');
const expectedChapterId = `${novelId}-${String(chapterNo).padStart(4, '0')}`;
if (chapterId !== expectedChapterId) fail(`chapter.next_chapter_id must equal ${expectedChapterId}`);
const workspaceFolderId = String(input.storage?.workspace_folder_id ?? '').trim();
if (!workspaceFolderId) fail('storage.workspace_folder_id is required');
const workspaceVersion = String(input.storage?.workspace_version ?? '').trim();
if (!workspaceVersion) fail('storage.workspace_version is required');
return [{json:{schema_version:'1.0',operation:'build_chapter_context',novel:{novel_id:novelId,novel_name:novelName},chapter:{next_chapter_no:chapterNo,next_chapter_id:chapterId},storage:{workspace_folder_id:workspaceFolderId,workspace_version:workspaceVersion},knowledge:{},sheets:{}}}];

