const state = $input.first()?.json ?? {};
const warnings = [], missing = [];
const asArray = v => Array.isArray(v) ? v : (v && typeof v === 'object' && Array.isArray(v.items) ? v.items : []);
const text = v => typeof v === 'string' ? v : JSON.stringify(v ?? '');
const tokens = v => text(v).toLowerCase();
const int = v => { const n=Number(v); return Number.isInteger(n)&&n>0?n:null; };
const safeArray = (value, field) => { if (Array.isArray(value)) return value; if (value==null || value==='') return []; if (typeof value==='string') { try { const x=JSON.parse(value); if(Array.isArray(x)) return x; } catch {} } warnings.push({code:'INVALID_SHEET_JSON',severity:'warning',field}); return []; };
const expected = {'StoryBible.json':'high','Canon.json':'high','Characters.json':'warning','World.json':'warning','Timeline.json':'warning','Conflicts.json':'warning','KnowledgeIndex.json':'warning'};
for (const [file,severity] of Object.entries(expected)) { const s=state.knowledge?.[file]; if(!s?.found){ missing.push(file); warnings.push({code:'MISSING_KNOWLEDGE_SOURCE',severity,file_name:file}); } else if(!s.valid) warnings.push({code:'INVALID_KNOWLEDGE_JSON',severity,file_name:file}); }
const sheet = name => Array.isArray(state.sheets?.[name]) ? state.sheets[name] : [];
for (const name of ['Story Progress','Foreshadowing Database','Foreshadowing History','Chapter Plan']) if (!sheet(name).length) missing.push(name);
const next=state.chapter.next_chapter_no, novelId=state.novel.novel_id;
const chapters=sheet('Chapter Database').filter(r=>String(r.novel_id??'').trim()===novelId && int(r.chapter_no) && Number(r.chapter_no)<next).sort((a,b)=>Number(a.chapter_no)-Number(b.chapter_no));
const detailed=chapters.slice(-3), eventIndex=chapters.slice(-10).map(r=>({chapter_id:r.chapter_id??null,chapter_no:Number(r.chapter_no),title:r.title??'',summary:r.summary??r.chapter_summary??'',events:safeArray(r.events_json,'Chapter Database.events_json')}));
const progressRows=sheet('Story Progress').filter(r=>String(r.novel_id??'').trim()===novelId && int(r.chapter_no) && Number(r.chapter_no)<next).sort((a,b)=>Number(b.chapter_no)-Number(a.chapter_no));
const p=progressRows[0]??null;
const storyProgress=p?{main_story:{progress_id:p.progress_id??null,chapter_no:Number(p.chapter_no),arc_name:p.arc_name??'',summary:p.summary??'',current_goal:p.current_goal??'',source_chapter_id:p.source_chapter_id??null},active_threads:safeArray(p.unresolved_threads_json,'Story Progress.unresolved_threads_json'),active_characters:safeArray(p.active_characters_json,'Story Progress.active_characters_json'),active_factions:safeArray(p.faction_states_json,'Story Progress.faction_states_json'),key_items:safeArray(p.key_items_json,'Story Progress.key_items_json'),constraints:safeArray(p.next_constraints,'Story Progress.next_constraints')}:{main_story:{},active_threads:[],active_characters:[],active_factions:[],key_items:[],constraints:[]};
const foreshadows=sheet('Foreshadowing Database').filter(r=>String(r.novel_id??'').trim()===novelId && !['resolved','abandoned'].includes(String(r.lifecycle_status??'').toLowerCase()));
const dormant=foreshadows.filter(r=>String(r.lifecycle_status).toLowerCase()==='dormant');
const active=foreshadows.filter(r=>String(r.lifecycle_status).toLowerCase()==='active');
const signalText=tokens([detailed,storyProgress]);
const enriched=active.map(f=>{ const deps=safeArray(f.dependencies_json,`Foreshadowing Database.${f.foreshadow_id}.dependencies_json`); const start=Number(f.resolution_window_start),end=Number(f.resolution_window_end),last=Number(f.last_touched_chapter||f.planted_chapter||0),cool=Number(f.min_touch_interval||0),priority=String(f.priority??'').toLowerCase(); const related=[f.title,f.description,deps].some(x=>x&&signalText.includes(tokens(x))); const inWindow=Number.isFinite(start)&&next>=start, overdue=Number.isFinite(end)&&next>end, cooled=next-last>=cool; return {...f,dependencies:deps,context_classification:{in_resolution_window:inWindow,overdue,cooled,related}};});
const must=enriched.filter(f=>f.context_classification.overdue||f.context_classification.in_resolution_window||['high','critical','urgent','p0','p1'].includes(String(f.priority).toLowerCase()));
const mustIds=new Set(must.map(f=>String(f.foreshadow_id))); const relevant=enriched.filter(f=>!mustIds.has(String(f.foreshadow_id))&&f.context_classification.related&&f.context_classification.cooled); const relevantIds=new Set(relevant.map(f=>String(f.foreshadow_id))); const background=enriched.filter(f=>!mustIds.has(String(f.foreshadow_id))&&!relevantIds.has(String(f.foreshadow_id)));
const historyIds=new Set([...must,...relevant,...dormant].map(f=>String(f.foreshadow_id)));
const grouped={}; for(const h of sheet('Foreshadowing History').filter(h=>String(h.novel_id??'').trim()===novelId&&historyIds.has(String(h.foreshadow_id)))) (grouped[h.foreshadow_id]??=[]).push(h);
const history=Object.values(grouped).flatMap(a=>a.sort((x,y)=>(Number(y.chapter_no)||0)-(Number(x.chapter_no)||0)||String(y.created_at??'').localeCompare(String(x.created_at??''))).slice(0,5));
const entitySignals=tokens([detailed,storyProgress,must,relevant]);
const kval=file=>state.knowledge?.[file]?.valid?state.knowledge[file].value:null;
const characters=asArray(kval('Characters.json')).filter(c=>[c.character_name,c.aliases,c.relationship_to_protagonist].some(v=>v&&entitySignals.includes(tokens(v))));
const worlds=asArray(kval('World.json')).filter(w=>[w.world_name,w.aliases,w.region,w.leader,w.members,w.related_factions,w.related_locations,w.rules,w.status].some(v=>v&&entitySignals.includes(tokens(v))));
const activeSignals=tokens([characters,worlds,storyProgress,must,relevant]);
const timeline=asArray(kval('Timeline.json')).filter(t=>Number(t.chapter_number)>=next-10||[t.participants,t.locations,t.factions,t.aliases,t.event_type].some(v=>v&&activeSignals.includes(tokens(v)))).sort((a,b)=>(Number(b.chapter_number)||0)-(Number(a.chapter_number)||0)||(Number(b.event_order)||0)-(Number(a.event_order)||0));
const plans=sheet('Chapter Plan').filter(r=>String(r.novel_id??'').trim()===novelId);
const previousPlan=plans.find(r=>Number(r.chapter_no)===next-1)??null;
const previousActual=chapters.find(r=>Number(r.chapter_no)===next-1)??(p&&Number(p.chapter_no)===next-1?p:null);
let delta=null; if(previousPlan&&previousActual) delta={planned:{chapter_no:next-1,summary:previousPlan.summary??previousPlan.plan_summary??'',goal:previousPlan.goal??previousPlan.chapter_goal??''},actual:{chapter_no:next-1,summary:previousActual.summary??previousActual.chapter_summary??'',goal:previousActual.current_goal??''},is_canonical:false};
let preview=[]; if(previousPlan){ const raw=previousPlan.short_horizon_preview_json??previousPlan.future_chapters_json??previousPlan.preview_json; preview=safeArray(raw,'Chapter Plan.short_horizon_preview').slice(0,5).map(x=>({...((x&&typeof x==='object')?x:{direction:x}),is_canon:false})); }
const core={}; if(kval('StoryBible.json')!==null) core.story_bible=kval('StoryBible.json'); if(kval('Canon.json')!==null) core.canon=kval('Canon.json');
const output={ok:true,schema_version:'1.0',operation:'build_chapter_context',chapter_context:{novel_id:novelId,novel_name:state.novel.novel_name,next_chapter_no:next,next_chapter_id:state.chapter.next_chapter_id,workspace_folder_id:state.storage.workspace_folder_id,workspace_version:state.storage.workspace_version},recent_story:{detailed_chapters:detailed,recent_event_index:eventIndex},canon_context:{core_canon:core,relevant_characters:characters,relevant_world:worlds,relevant_timeline:timeline,conflict_warnings:asArray(kval('Conflicts.json')),knowledge_health:(kval('KnowledgeIndex.json')&&typeof kval('KnowledgeIndex.json')==='object'&&!Array.isArray(kval('KnowledgeIndex.json')))?kval('KnowledgeIndex.json'):{}},story_progress:storyProgress,foreshadowing_context:{must_consider:must,relevant,background,dormant,history},planning_memory:{previous_plan:previousPlan,previous_actual:previousActual,continuity_delta:delta,short_horizon_preview:preview},context_meta:{missing_sources:[...new Set(missing)],warnings,recent_chapter_count:detailed.length,relevant_character_count:characters.length,relevant_world_count:worlds.length,relevant_timeline_count:timeline.length,must_consider_foreshadow_count:must.length,relevant_foreshadow_count:relevant.length}};
return [{json:output}];
